arguments.command:
python3 - <<'EOF'
src = open('test/playtest.mjs').read()

# nav tests: sim-time based (wall-clock waits race at software-render fps)
old = """// bot AI movement over time (move player back to spawn so bots patrol)
const move = await page.evaluate(async () => {
  GAME.test.pose(0, 0, 27, 0, 0);
  const a = GAME.test.botInfo().map(b => [...b.pos]);
  await new Promise(r => setTimeout(r, 2500));
  const b = GAME.test.botInfo().map(x => [...x.pos]);
  let moved = 0;
  for (let i = 0; i < a.length; i++) {
    const d = Math.hypot(a[i][0] - b[i][0], a[i][2] - b[i][2]);
    if (d > 0.5) moved++;
  }
  return { moved, total: a.length };
});
check('bot AI navigates the map', move.moved >= 1, `${move.moved}/${move.total} bots moved`);"""
new = """// bot AI movement over SIM time (wall-clock waits race at software fps)
const move = await page.evaluate(async () => {
  GAME.test.pose(0, 0, 27, 0, 0);
  const a = GAME.test.botInfo().map(b => [...b.pos]);
  const t0 = GAME.game.time;
  while (GAME.game.time - t0 < 3) await new Promise(r => setTimeout(r, 200));
  const b = GAME.test.botInfo().map(x => [...x.pos]);
  let moved = 0;
  for (let i = 0; i < a.length; i++) {
    const d = Math.hypot(a[i][0] - b[i][0], a[i][2] - b[i][2]);
    if (d > 0.5) moved++;
  }
  return { moved, total: a.length };
});
check('bot AI navigates the map', move.moved >= 1, `${move.moved}/${move.total} bots moved`);"""
assert old in src
src = src.replace(old, new)

old = """// bots navigate on each new map
for (const mapId of ['foundry', 'canopy']) {
  const nav = await page.evaluate(async id => {
    GAME.test.start(id);
    GAME.test.skipBuy();
    const sp = GAME.game.map.PLAYER_SPAWN;
    GAME.test.pose(sp.x, 0, sp.z, 0, 0);
    await new Promise(r => setTimeout(r, 400));
    const a = GAME.test.botInfo().map(b => [...b.pos]);
    await new Promise(r => setTimeout(r, 2500));
    const b = GAME.test.botInfo().map(x => [...x.pos]);
    let moved = 0;
    for (let i = 0; i < a.length; i++) {
      if (Math.hypot(a[i][0] - b[i][0], a[i][2] - b[i][2]) > 0.5) moved++;
    }
    return { moved, total: a.length };
  }, mapId);
  check(`bots navigate "${mapId}"`, nav.moved >= 1, `${nav.moved}/${nav.total} moved`);
}"""
new = """// bots navigate on each new map (sim-time budgeted)
for (const mapId of ['foundry', 'canopy', 'bastion']) {
  const nav = await page.evaluate(async id => {
    GAME.test.start(id);
    GAME.test.skipBuy();
    const sp = GAME.game.map.PLAYER_SPAWN;
    GAME.test.pose(sp.x, 0, sp.z, 0, 0);
    const a = GAME.test.botInfo().map(b => [...b.pos]);
    const t0 = GAME.game.time;
    while (GAME.game.time - t0 < 3) await new Promise(r => setTimeout(r, 200));
    const b = GAME.test.botInfo().map(x => [...x.pos]);
    let moved = 0;
    for (let i = 0; i < a.length; i++) {
      if (Math.hypot(a[i][0] - b[i][0], a[i][2] - b[i][2]) > 0.5) moved++;
    }
    return { moved, total: a.length };
  }, mapId);
  check(`bots navigate "${mapId}"`, nav.moved >= 1, `${nav.moved}/${nav.total} moved`);
}"""
assert old in src
src = src.replace(old, new)
open('test/playtest.mjs', 'w').write(src)
print('playtest patched')
EOF
cd test && node playtest.mjs 2>&1 | grep -E '✘|checks passed'
